def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    # The shapes are tiled by 2x2 squares and L triominoes.
    # Find a complete tiling, requiring square pieces to have color 1.
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = frozenset(((r,c), (r+1,c), (r,c+1), (r+1,c+1)))
            pieces.append((square, 1))
            box = set(square)
            for missing in box:
                tri = frozenset(box - {missing})
                # Missing upper-left -> 2, lower-left -> 3, upper-right -> 4.
                mr, mc = missing
                color = 2 if (mr, mc) in ((r,c), (r+1,c+1)) else (3 if mr == r+1 else 4)
                pieces.append((tri, color))

    def solve(left, chosen):
        if not left:
            return chosen
        cell = min(left)
        for shape, color in pieces:
            if cell in shape and shape <= left:
                ans = solve(left - shape, chosen + [(shape, color)])
                if ans is not None:
                    return ans
        return None

    tiling = solve(cells, [])
    if tiling:
        for shape, color in tiling:
            for r, c in shape:
                out[r][c] = color
    return out
